// Web bundle pack, sign and verify (issue 1626; web-serving-architecture.md §3.1),
// against REAL ssh-keygen keys made in a mkdtemp dir. No private key is ever
// committed: every key here is generated by the test and deleted after it.
//
// The negative cases are the point: a changed byte, a wrong digest, a missing
// signature, an unlisted key and a foreign namespace each refuse the bundle AND
// leave the destination's parent exactly as it was.
//
// Runs in the required `unit.yml` job (`bun run test:unit`). ssh-keygen is
// asserted present, never skipped around.
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, utimesSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";
import { gunzipSync, gzipSync } from "node:zlib";
import { createHash } from "node:crypto";
import { signDetached } from "../../../backend/scripts/lib/rollout-signing.ts";
import {
  BUNDLE_MANIFEST_FILENAME,
  WEB_BUNDLE_SIGNATURE_NAMESPACE,
  digestStatement,
  parseBundleFileName,
  serialiseBundleManifest,
} from "../../lib/web-bundle-manifest.ts";
import {
  WEB_BUNDLE_ALLOWED_SIGNERS,
  packBundle,
  readTar,
  signBundle,
  verifyBundle,
  writeTar,
} from "../../lib/web-bundle.ts";

const PRINCIPAL = "web-bundle@test";
const VERSION = { name: "@robotmoney/web-client", version: "0.1.0", commit: "0edfad37", apiRange: "^0.5.0" };

let root: string;
let site: string;
let key: string;
let stranger: string;
let allowed: string;

function sh(cmd: string[]): { code: number; err: string } {
  const r = Bun.spawnSync(cmd, { stdout: "pipe", stderr: "pipe" });
  return { code: r.exitCode ?? -1, err: new TextDecoder().decode(r.stderr) };
}

function keygen(path: string): void {
  const r = sh(["ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-C", "test", "-f", path]);
  if (r.code !== 0) throw new Error(`ssh-keygen failed: ${r.err}`);
}

function sha256(data: Uint8Array): string {
  return createHash("sha256").update(data).digest("hex");
}

/** A fresh scratch dir with one signed bundle copied in, for a single case to tamper with. */
function signedCopy(): { dir: string; bundle: string } {
  const dir = mkdtempSync(join(root, "case-"));
  const packed = packBundle(site, join(dir, "out"));
  signBundle(packed.path, key);
  return { dir, bundle: packed.path };
}

/** Verify into `<dir>/dest` and assert a refusal that wrote nothing. */
function expectRefusedAndNothingWritten(dir: string, bundle: string, allowedSigners = allowed): string {
  const before = readdirSync(dir).sort();
  const dest = join(dir, "dest");
  const r = verifyBundle(bundle, dest, { allowedSigners });
  expect(r.ok).toBe(false);
  expect(existsSync(dest)).toBe(false);
  expect(readdirSync(dir).sort()).toEqual(before);
  return r.ok ? "" : r.reason;
}

beforeAll(() => {
  expect({ tool: "ssh-keygen", present: sh(["ssh-keygen", "-A", "-h"]).code !== 127 }).toEqual({ tool: "ssh-keygen", present: true });
  root = mkdtempSync(join(tmpdir(), "web-bundle-"));
  site = join(root, "site");
  mkdirSync(join(site, "assets", "js"), { recursive: true });
  mkdirSync(join(site, "about"), { recursive: true });
  writeFileSync(join(site, "index.html"), "<!doctype html><title>home</title>\n");
  writeFileSync(join(site, "about", "index.html"), "<!doctype html><title>about</title>\n");
  writeFileSync(join(site, "assets", "js", "app.js"), "console.log('hi');\n".repeat(100));
  writeFileSync(join(site, "assets", "logo.bin"), new Uint8Array(1500).map((_, i) => i % 256));
  writeFileSync(join(site, "version.json"), `${JSON.stringify(VERSION)}\n`);
  key = join(root, "key");
  stranger = join(root, "stranger");
  keygen(key);
  keygen(stranger);
  const [type, blob] = readFileSync(`${key}.pub`, "utf8").trim().split(/\s+/);
  allowed = join(root, "allowed-signers");
  writeFileSync(allowed, `# test trust root\n${PRINCIPAL} namespaces="${WEB_BUNDLE_SIGNATURE_NAMESPACE}" ${type} ${blob}\n`);
});

afterAll(() => {
  if (root) rmSync(root, { recursive: true, force: true });
});

describe("pack", () => {
  test("packing one tree twice gives byte-identical tarballs and equal sha256, whatever the mtimes", () => {
    const a = packBundle(site, join(root, "pack-a"));
    utimesSync(join(site, "index.html"), new Date(1_000_000_000_000), new Date(1_000_000_000_000));
    utimesSync(join(site, "assets", "logo.bin"), new Date(), new Date());
    const b = packBundle(site, join(root, "pack-b"));
    expect(basename(a.path)).toBe(basename(b.path));
    expect(Buffer.compare(readFileSync(a.path), readFileSync(b.path))).toBe(0);
    expect(a.sha256).toBe(b.sha256);
    expect(sha256(readFileSync(a.path))).toBe(a.sha256);
    expect(readFileSync(a.digestPath, "utf8")).toBe(digestStatement(a.sha256, basename(a.path)));
  });

  test("the tarball's version.json version and commit equal the file name", () => {
    const p = packBundle(site, join(root, "pack-name"));
    expect(basename(p.path)).toBe(`robotmoney-web-${VERSION.version}-${VERSION.commit}.tar.gz`);
    const files = readTar(gunzipSync(readFileSync(p.path)));
    const v = JSON.parse(new TextDecoder().decode(files.find((f) => f.path === "version.json")!.data));
    expect(parseBundleFileName(basename(p.path))).toEqual({ version: v.version, commit: v.commit });
  });

  test("entries are sorted, owned by 0, mtime 0, and the manifest lists every other file with its sha256", () => {
    const p = packBundle(site, join(root, "pack-shape"));
    const tar = gunzipSync(readFileSync(p.path));
    const files = readTar(tar);
    const paths = files.map((f) => f.path);
    expect(paths).toEqual([...paths].sort());
    expect(paths).toContain(BUNDLE_MANIFEST_FILENAME);
    // First header: uid, gid and mtime fields are all zero.
    const field = (off: number, len: number) => new TextDecoder().decode(tar.subarray(off, off + len)).replace(/\0.*$/, "");
    expect(Number.parseInt(field(108, 8), 8)).toBe(0);
    expect(Number.parseInt(field(116, 8), 8)).toBe(0);
    expect(Number.parseInt(field(136, 12), 8)).toBe(0);
    const manifest = JSON.parse(new TextDecoder().decode(files.find((f) => f.path === BUNDLE_MANIFEST_FILENAME)!.data));
    const content = files.filter((f) => f.path !== BUNDLE_MANIFEST_FILENAME);
    expect(manifest.files).toEqual(content.map((f) => ({ path: f.path, sha256: sha256(f.data), size: f.data.length })));
  });
});

describe("verify", () => {
  test("a bundle signed by a listed key verifies and extracts the exact tree", () => {
    const { dir, bundle } = signedCopy();
    const dest = join(dir, "dest");
    const r = verifyBundle(bundle, dest, { allowedSigners: allowed });
    expect(r).toMatchObject({ ok: true, principal: PRINCIPAL, version: VERSION.version, commit: VERSION.commit });
    expect(readFileSync(join(dest, "assets", "js", "app.js"))).toEqual(readFileSync(join(site, "assets", "js", "app.js")));
    expect(readFileSync(join(dest, "assets", "logo.bin"))).toEqual(readFileSync(join(site, "assets", "logo.bin")));
    // Nothing but the destination appeared beside it: the staging dir was renamed, not left behind.
    expect(readdirSync(dir).sort()).toEqual(["dest", "out"]);
  });

  test("a changed byte fails verification and writes nothing", () => {
    const { dir, bundle } = signedCopy();
    const bytes = readFileSync(bundle);
    bytes[bytes.length - 20] ^= 0xff;
    writeFileSync(bundle, bytes);
    expect(expectRefusedAndNothingWritten(dir, bundle)).toContain("digest");
  });

  test("a wrong digest fails verification and writes nothing", () => {
    const { dir, bundle } = signedCopy();
    writeFileSync(`${bundle}.sha256`, digestStatement("0".repeat(64), basename(bundle)));
    expect(expectRefusedAndNothingWritten(dir, bundle)).toContain("digest");
  });

  test("a missing signature fails verification and writes nothing", () => {
    const { dir, bundle } = signedCopy();
    rmSync(`${bundle}.sha256.sig`);
    expect(expectRefusedAndNothingWritten(dir, bundle)).toContain("signature is missing");
  });

  test("a signature from a key not in allowed-signers fails verification and writes nothing", () => {
    const { dir, bundle } = signedCopy();
    signBundle(bundle, stranger);
    expect(expectRefusedAndNothingWritten(dir, bundle)).toContain("no key");
  });

  test("a valid bundle checked against the committed allowed-signers (bootstrap key only) is refused", () => {
    const { dir, bundle } = signedCopy();
    expect(expectRefusedAndNothingWritten(dir, bundle, WEB_BUNDLE_ALLOWED_SIGNERS)).toContain("no key");
  });

  test("a renamed bundle fails: the signed statement names the original file", () => {
    const { dir, bundle } = signedCopy();
    const renamed = join(dir, "out", "robotmoney-web-9.9.9-0edfad37.tar.gz");
    for (const ext of ["", ".sha256", ".sha256.sig"]) copyFileSync(`${bundle}${ext}`, `${renamed}${ext}`);
    expect(expectRefusedAndNothingWritten(dir, renamed)).toContain("digest");
  });

  test("a signed bundle whose files do not match its manifest fails and writes nothing", () => {
    const dir = mkdtempSync(join(root, "case-"));
    const out = join(dir, "out");
    mkdirSync(out);
    const enc = new TextEncoder();
    const index = enc.encode("<p>real</p>\n");
    const version = enc.encode(`${JSON.stringify(VERSION)}\n`);
    const manifest = serialiseBundleManifest([
      { path: "index.html", sha256: "1".repeat(64), size: index.length },
      { path: "version.json", sha256: sha256(version), size: version.length },
    ]);
    const gz = gzipSync(writeTar([
      { path: BUNDLE_MANIFEST_FILENAME, data: enc.encode(manifest) },
      { path: "index.html", data: index },
      { path: "version.json", data: version },
    ]));
    const bundle = join(out, `robotmoney-web-${VERSION.version}-${VERSION.commit}.tar.gz`);
    writeFileSync(bundle, gz);
    writeFileSync(`${bundle}.sha256`, digestStatement(sha256(gz), basename(bundle)));
    signBundle(bundle, key);
    expect(expectRefusedAndNothingWritten(dir, bundle)).toContain("index.html");
  });
});

describe("namespace", () => {
  test("the namespace is robotmoney-web-bundle@v1", () => {
    expect(WEB_BUNDLE_SIGNATURE_NAMESPACE).toBe("robotmoney-web-bundle@v1");
  });

  test("a signature in another namespace, by a listed key, fails verification and writes nothing", () => {
    const { dir, bundle } = signedCopy();
    const sig = signDetached(readFileSync(`${bundle}.sha256`, "utf8"), key, "rollout-receipt.v1");
    expect(sig).not.toBeNull();
    writeFileSync(`${bundle}.sha256.sig`, sig!);
    expect(expectRefusedAndNothingWritten(dir, bundle)).toContain("no key");
  });
});

describe("committed website-server/allowed-signers", () => {
  test("holds public keys only, each scoped to the web-bundle namespace", () => {
    const text = readFileSync(WEB_BUNDLE_ALLOWED_SIGNERS, "utf8");
    expect(text).not.toContain("PRIVATE KEY");
    const lines = text.split("\n").filter((l) => l.trim() && !l.startsWith("#"));
    expect(lines.length).toBeGreaterThan(0);
    for (const line of lines) {
      expect(line).toMatch(/^\S+ namespaces="robotmoney-web-bundle@v1" ssh-ed25519 AAAA[0-9A-Za-z+/]+=*$/);
    }
  });
});
